<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { documentApi } from '@/api/business'
import { systemApi } from '@/api/system'
const loading=ref(false),rows=ref<any[]>([]),departments=ref<any[]>([]),visible=ref(false),editingId=ref<number|null>(null),versionsVisible=ref(false),queryVisible=ref(false),previewVisible=ref(false),previewMode=ref(''),previewUrl=ref(''),previewHtml=ref(''),previewTitle=ref(''),versions=ref<any[]>([]),selected=ref<any>(),selectedFilePath=ref('')
const form=reactive({documentNo:'',title:'',category:'体系文件',securityLevel:'INTERNAL',ownerDeptId:null as number|null,versionNo:'V1.0',fileName:'',storagePath:'',fileContentBase64:'',fileContentType:'',fileSize:0,revisionNote:'首次发布',reviewDueAt:'',version:0})
const query=reactive({keyword:'',category:'',ownerDeptId:null as number|null,status:'',securityLevel:''})
const appliedQuery=ref({...query})
const filteredRows=computed(()=>rows.value.filter((row:any)=>{const q=appliedQuery.value;const keyword=q.keyword.trim().toLowerCase();return(!keyword||String(row.documentNo||'').toLowerCase().includes(keyword)||String(row.title||'').toLowerCase().includes(keyword))&&(!q.category||row.category===q.category)&&(!q.ownerDeptId||row.ownerDeptId===q.ownerDeptId)&&(!q.status||row.status===q.status)&&(!q.securityLevel||row.securityLevel===q.securityLevel)}))
async function load(){loading.value=true;try{[rows.value,departments.value]=await Promise.all([documentApi.list(),systemApi.departments()])}finally{loading.value=false}}
function generateDocumentNo(){const now=new Date();const pad=(value:number,length=2)=>String(value).padStart(length,'0');const timestamp=`${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}${pad(now.getMilliseconds(),3)}`;const suffix=Math.random().toString(36).slice(2,6).toUpperCase();return `WD${timestamp}-${suffix}`}
function handleFileSelect(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;const browserPath=input.value||file.name;selectedFilePath.value=browserPath;form.fileName=file.name;form.storagePath=browserPath;form.fileContentType=file.type||'application/octet-stream';form.fileSize=file.size;form.title=file.name.replace(/\.[^.]+$/,'');if(!editingId.value)form.documentNo=generateDocumentNo();const reader=new FileReader();reader.onload=()=>{form.fileContentBase64=String(reader.result||'')};reader.onerror=()=>ElMessage.error('读取文件内容失败');reader.readAsDataURL(file)}
function create(){editingId.value=null;selectedFilePath.value='';const now=new Date();const today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;Object.assign(form,{documentNo:'',title:'',category:'体系文件',securityLevel:'INTERNAL',ownerDeptId:null,versionNo:'V1.0',fileName:'',storagePath:'',fileContentBase64:'',fileContentType:'',fileSize:0,revisionNote:'首次发布',reviewDueAt:today,version:0});visible.value=true}
async function edit(row:any){const current=(await documentApi.versions(row.id)).find((item:any)=>item.versionNo===row.currentVersionNo);editingId.value=row.id;selectedFilePath.value=current?.storagePath||current?.fileName||'';Object.assign(form,{documentNo:row.documentNo,title:row.title,category:row.category,securityLevel:row.securityLevel,ownerDeptId:row.ownerDeptId,versionNo:row.currentVersionNo,fileName:current?.fileName||'',storagePath:current?.storagePath||'',fileContentBase64:'',fileContentType:'',fileSize:0,revisionNote:current?.revisionNote||'',reviewDueAt:current?.reviewDueAt||'',version:row.version});visible.value=true}
async function save(){if(!editingId.value&&!form.fileName){ElMessage.warning('请选择文件');return}if(!editingId.value&&!form.fileContentBase64){ElMessage.warning('文件内容正在读取，请稍后再试');return}if(editingId.value)await documentApi.update(editingId.value,form);else await documentApi.create(form);visible.value=false;ElMessage.success(editingId.value?'受控文件已修改':'受控文件已创建');await load()}
async function download(row:any){try{const response=await documentApi.download(row.id);const disposition=String(response.headers['content-disposition']||'');const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];const quoted=disposition.match(/filename="?([^";]+)"?/i)?.[1];const fileName=encoded?decodeURIComponent(encoded):quoted||row.title;const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download=fileName;link.click();URL.revokeObjectURL(url);ElMessage.success('文件下载已开始')}catch(error:any){ElMessage.error(error?.response?.data?.message||'文件下载失败')}}
async function preview(row:any){try{const current=(await documentApi.versions(row.id)).find((item:any)=>item.versionNo===row.currentVersionNo);const name=String(current?.fileName||'').toLowerCase();previewTitle.value=`文件预览 - ${row.title}`;if(/\.(docx?|xlsx?)$/.test(name)){const data=await documentApi.previewText(row.id);previewMode.value='html';previewHtml.value=data.html;previewUrl.value=''}else if(/\.(jpg|jpeg|png|gif|bmp|webp)$/.test(name)){const response=await documentApi.download(row.id);previewMode.value='image';previewUrl.value=URL.createObjectURL(response.data);previewHtml.value=''}else if(name.endsWith('.pdf')){const response=await documentApi.download(row.id);previewMode.value='pdf';previewUrl.value=URL.createObjectURL(response.data);previewHtml.value=''}else{ElMessage.warning('该文件类型暂不支持在线预览，请下载后查看');return}previewVisible.value=true}catch(error:any){ElMessage.error(error?.response?.data?.message||'文件预览失败')}}
function closePreview(){previewVisible.value=false;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewHtml.value=''}
async function remove(row:any){try{await ElMessageBox.confirm(`确定删除受控文件“${row.title}”吗？`,'删除受控文件',{type:'warning'});await documentApi.delete(row.id);ElMessage.success('受控文件已删除');await load()}catch(error:any){if(error==='cancel'||error==='close')return;ElMessage.error(error?.response?.data?.message||'删除受控文件失败')}}
async function openVersions(row:any){selected.value=row;versions.value=await documentApi.versions(row.id);versionsVisible.value=true}
async function act(v:any,type:string){if(type==='submit')await documentApi.submit(v.id);if(type==='review'){const approved=await ElMessageBox.confirm('选择“确定”表示审核通过，选择“取消”不执行','文件审核').then(()=>true).catch(()=>false);if(!approved)return;await documentApi.review(v.id,{approved:true,comment:'审核通过'})}if(type==='reject')await documentApi.review(v.id,{approved:false,comment:'退回修改'});if(type==='publish')await documentApi.publish(v.id);ElMessage.success('操作成功');versions.value=await documentApi.versions(selected.value.id);await load()}
const state=(s:string)=>({DRAFT:'草稿',REVIEWING:'审核中',APPROVED:'待发布',REJECTED:'已退回',PUBLISHED:'已发布',SUPERSEDED:'历史版本',VOID:'已作废'} as any)[s]||s
const securityName=(s:string)=>({INTERNAL:'内部',RESTRICTED:'受限',PUBLIC:'公开'} as Record<string,string>)[s]||'未知'
function applyQuery(){appliedQuery.value={...query};queryVisible.value=false;ElMessage.success(`查询完成，共 ${filteredRows.value.length} 条记录`)}
function resetQuery(){Object.assign(query,{keyword:'',category:'',ownerDeptId:null,status:'',securityLevel:''});appliedQuery.value={...query};ElMessage.success('查询条件已重置，已恢复全部文件')}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p>DOCUMENT CONTROL</p><h1>文件管理</h1></div></div><div class="module-tabs"><span class="active">文件库</span></div><div class="document-action-bar"><el-button type="primary" @click="create">文件入库</el-button><div class="document-query-actions"><el-button type="primary" @click="queryVisible=true">查询</el-button><el-button @click="resetQuery">重置</el-button></div></div><div class="content-card"><el-table v-loading="loading" :data="filteredRows"><el-table-column prop="documentNo" label="文件编号" width="150"/><el-table-column prop="title" label="文件名称"/><el-table-column prop="currentVersionNo" label="版本" width="80"/><el-table-column prop="category" label="分类"/><el-table-column prop="departmentName" label="归属部门"/><el-table-column label="密级"><template #default="s">{{securityName(s.row.securityLevel)}}</template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.status==='PUBLISHED'?'success':s.row.status==='REVIEWING'?'warning':'info'">{{state(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="430" fixed="right"><template #default="s"><div class="document-row-actions"><el-button v-if="s.row.status!=='PUBLISHED'" class="document-row-action version-action" @click="openVersions(s.row)">版本与审批</el-button><el-button v-if="['DRAFT','REJECTED'].includes(s.row.status)" class="document-row-action edit-action" @click="edit(s.row)">修改</el-button><el-button v-if="s.row.status==='PUBLISHED'" class="document-row-action preview-action" @click="preview(s.row)">预览</el-button><el-button v-if="s.row.status==='PUBLISHED'" class="document-row-action download-action" @click="download(s.row)">下载</el-button><el-button v-if="['DRAFT','REJECTED'].includes(s.row.status)" class="document-row-action delete-action" @click="remove(s.row)">删除</el-button></div></template></el-table-column></el-table></div>
<el-dialog v-model="queryVisible" title="查询文件库" width="580px"><el-form label-width="90px"><el-form-item label="编号/名称"><el-input v-model="query.keyword" clearable placeholder="请输入文件编号或名称"/></el-form-item><el-form-item label="分类"><el-select v-model="query.category" clearable placeholder="全部分类"><el-option v-for="x in ['体系文件','程序文件','作业指导书','记录表格','标准文本','常用文件']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="归属部门"><el-select v-model="query.ownerDeptId" clearable placeholder="全部部门"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="密级"><el-select v-model="query.securityLevel" clearable placeholder="全部密级"><el-option label="内部" value="INTERNAL"/><el-option label="受限" value="RESTRICTED"/><el-option label="公开" value="PUBLIC"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="全部状态"><el-option label="草稿" value="DRAFT"/><el-option label="审核中" value="REVIEWING"/><el-option label="待发布" value="APPROVED"/><el-option label="已退回" value="REJECTED"/><el-option label="已发布" value="PUBLISHED"/><el-option label="已作废" value="VOID"/></el-select></el-form-item></el-form><template #footer><el-button @click="resetQuery">重置</el-button><el-button @click="queryVisible=false">取消</el-button><el-button type="primary" @click="applyQuery">查询</el-button></template></el-dialog>
<el-dialog v-model="visible" :title="editingId?'修改受控文件':'新建受控文件'" width="620px"><el-form label-width="90px"><el-form-item class="file-picker-item"><div class="file-select-field"><label class="file-select-button">选择文件<input type="file" @change="handleFileSelect"/></label><el-input :model-value="selectedFilePath" readonly placeholder="请选择本地文件"/></div></el-form-item><el-form-item label="文件标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="文件编号"><el-input v-model="form.documentNo" readonly placeholder="选择文件后自动生成"/></el-form-item><el-form-item label="密级"><el-select v-model="form.securityLevel" style="width:100%"><el-option label="内部" value="INTERNAL"/><el-option label="受限" value="RESTRICTED"/><el-option label="公开" value="PUBLIC"/></el-select></el-form-item><el-form-item label="归属部门"><el-select v-model="form.ownerDeptId" style="width:100%"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="版本号"><el-input v-model="form.versionNo" :disabled="!!editingId"/></el-form-item><el-form-item label="修订说明"><el-input v-model="form.revisionNote" type="textarea"/></el-form-item><el-form-item label="复审日期"><el-date-picker v-model="form.reviewDueAt" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">{{editingId?'保存修改':'保存草稿'}}</el-button></template></el-dialog>
<el-dialog v-model="previewVisible" :title="previewTitle" width="88%" top="4vh" destroy-on-close @closed="closePreview"><div class="preview-container"><img v-if="previewMode==='image'" :src="previewUrl" class="image-preview"/><iframe v-else-if="previewMode==='pdf'" :src="previewUrl" class="pdf-preview"></iframe><div v-else-if="previewMode==='html'" class="office-preview" v-html="previewHtml"></div></div></el-dialog><el-dialog v-model="versionsVisible" title="版本历史与审批" width="820px"><el-table :data="versions"><el-table-column prop="versionNo" label="版本"/><el-table-column prop="fileName" label="附件"/><el-table-column prop="revisionNote" label="修订说明"/><el-table-column prop="reviewDueAt" label="复审日期"/><el-table-column label="状态"><template #default="s">{{state(s.row.status)}}</template></el-table-column><el-table-column label="操作" width="230"><template #default="s"><div class="version-row-actions"><el-button v-if="['DRAFT','REJECTED'].includes(s.row.status)" class="version-row-action version-submit-action" @click="act(s.row,'submit')">提交审核</el-button><template v-if="s.row.status==='REVIEWING'"><el-button class="version-row-action version-approve-action" @click="act(s.row,'review')">通过</el-button><el-button class="version-row-action version-reject-action" @click="act(s.row,'reject')">退回</el-button></template><el-button v-if="s.row.status==='APPROVED'" class="version-row-action version-publish-action" @click="act(s.row,'publish')">发布</el-button></div></template></el-table-column></el-table></el-dialog></section></template>

<style scoped>
.document-status-flow{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;padding:19px 28px;background:#fff;border:1px solid #dce2f6;box-shadow:0 8px 28px rgba(53,71,135,.05)}.document-status-flow article{min-width:72px;text-align:center}.document-status-flow b,.document-status-flow span{display:block}.document-status-flow b{font-size:25px;color:#396afc}.document-status-flow span{margin-top:4px;color:#7c8a86;font-size:12px}.document-status-flow i{color:#b8c4c0;font-style:normal;font-size:20px}.document-status-flow i.branch{color:#e49a2d}.document-action-bar{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.document-action-bar :deep(.el-button){height:38px;min-width:104px;font-weight:700}.document-query-actions{display:flex;align-items:center;gap:3px}.document-query-actions :deep(.el-button+.el-button){margin-left:0}.document-row-actions,.version-row-actions{display:flex;align-items:center;gap:5px}.document-row-actions :deep(.el-button+.el-button),.version-row-actions :deep(.el-button+.el-button){margin-left:0}.document-row-action,.version-row-action{height:38px;min-width:78px;border:0;border-radius:8px;color:#fff;font-size:14px;font-weight:800}.version-action{min-width:104px;background:linear-gradient(110deg,#6b70e8,#5546c7)}.edit-action,.version-submit-action{background:linear-gradient(110deg,#168bea,#396afc)}.preview-action{background:linear-gradient(110deg,#7b61e8,#9b55d6)}.download-action,.version-approve-action{background:linear-gradient(110deg,#0fa36f,#25bd8a)}.delete-action,.version-reject-action{background:linear-gradient(110deg,#f05c68,#d9364e)}.version-publish-action{background:linear-gradient(110deg,#f2a52b,#e67b18)}.version-submit-action{min-width:96px}.file-picker-item :deep(.el-form-item__content){margin-left:0!important}.file-select-field{display:flex;width:100%;gap:8px}.file-select-field :deep(.el-input){flex:1}.file-select-button{display:inline-flex;align-items:center;justify-content:center;min-width:92px;height:32px;border-radius:6px;background:linear-gradient(110deg,#168bea,#396afc);color:#fff;font-size:14px;font-weight:700;cursor:pointer}.file-select-button input{display:none}.preview-container{min-height:72vh;max-height:80vh;overflow:auto;background:#f3f5f9}.pdf-preview{width:100%;height:76vh;border:0}.image-preview{display:block;max-width:100%;margin:0 auto}.office-preview{min-height:72vh;padding:30px;background:#fff;color:#222;line-height:1.7}.office-preview :deep(table){width:100%;margin-bottom:24px;border-collapse:collapse}.office-preview :deep(td){padding:7px;border:1px solid #bbb}
</style>
